def pron(w):
 return 'Soa como “'+w.replace('j','r').replace('ll','i').replace('ñ','nh')+'”.'
def art(seed,work):
 return {'s':['plaza','cafe','market','street','gallery'][seed%5],'items':[['🗺️',25,35,14,'bob'],['☕',50,55,13,'bob'],['🧑',75,38,14,'bob'],['🎒',88,72,12,'bob']],'seed':f'a1-{seed}-{work[:4]}'}
def linepairs(topic, vocab, verbs, expr, region):
 lines=[['Persona local',f'En {region}, estamos en una situación real.',f'Em {region}, estamos em uma situação real.'],['Tú',f'Quisiera hablar de {topic}.',f'Eu gostaria de falar sobre {topic}.'],['Persona local',f'Primero, podemos {verbs[0]} y observar el contexto.',f'Primeiro, podemos {VERBPT[verbs[0]]} e observar o contexto.'],['Tú',f'Claro. {expr[0]}',f'Claro. {expr[0]}'],['Persona local',f'También necesitamos {verbs[1]} con calma.',f'Também precisamos {VERBPT[verbs[1]]} com calma.'],['Tú',f'{expr[1]}.',f'{expr[1]}.'],['Persona local',f'¿Puedes {verbs[2]} una opción?',f'Você pode {VERBPT[verbs[2]]} uma opção?'],['Tú',f'{expr[2]}.',f'{expr[2]}.']]
 return lines
def secondpairs(topic,vocab,verbs,expr):
 return [['Tú',f'En esta situación, quiero {verbs[3]} mejor.',f'Nesta situação, quero {VERBPT[verbs[3]]} melhor.'],['Persona local',f'Puedes usar la palabra {vocab[0]} aquí.',f'Você pode usar a palavra {vocab[0]} aqui.'],['Tú',f'{expr[0]} y {expr[1].lower()}.',f'{expr[0]} e {expr[1].lower()}.'],['Persona local',f'¿Qué necesitas ahora?', 'O que você precisa agora?'],['Tú',f'Necesito {vocab[1]} y una respuesta clara.',f'Preciso de {vocab[1]} e de uma resposta clara.'],['Persona local','Entonces, seguimos juntos.','Então, seguimos juntos.'],['Tú','Gracias por explicarlo.','Obrigado por explicar.'],['Persona local','Hasta la próxima situación.','Até a próxima situação.']]
def make(n,idx):
 work,year,region=WORKS[idx%len(WORKS)]; topic,vocab,verbs,expr=TOPICS[idx%len(TOPICS)]; title=f'{topic.capitalize()} · {work}'
 v=[ [w,PT.get(w,w),pron(w)] for w in vocab ]
 lines=linepairs(topic,vocab,verbs,expr,region); lines2=secondpairs(topic,vocab,verbs,expr)
 hot=[{'e':e,'en':w,'pt':PT.get(w,w),'say':f'La palabra {w} aparece en la situación.'} for e,w in zip(['🔤','🧭','📝','🎒','💬'],vocab[:5])]
 scene=lambda ls,rs='plaza': {'k':'pgscene','cast':{'Persona local':['🧑🏽','#5271a5'],'Tú':['🙂','#d05a6e']},'lines':ls,'speakers':{'Persona local':'polly','Tú':'tom'},'rs':rs,'chars':[['polly',35,0,1.0],['tom',68,1,1.0]],'say':'Ouça e leia a cena.'}
 pgspeak=[{'n':[l[1],l[2]],'o':[[l[1],l[2]],[vocab[i%6],PT.get(vocab[i%6],vocab[i%6])],[expr[i%4],expr[i%4]]],'a':0} for i,l in enumerate(lines[:5])]
 missions=[{'ic':'🎬','name':'Cena da obra','data':{'prompt':f'Responde en español: {topic} en el contexto de {work}.','ph':lines[1][1],'chips':vocab[:3],'model':lines[3][1],'check':['Usé una fórmula adecuada','Di una respuesta completa']} ,},{'ic':'🗣️','name':'Resposta guiada','data':{'prompt':f'Usa dos palabras nuevas para {topic}.','ph':lines2[0][1],'chips':vocab[2:5],'model':lines2[2][1],'check':['Usé el vocabulario','Mantuve la intención']}},{'ic':'✍️','name':'Produção livre','data':{'prompt':'Crie uma fala nova para a situação.','ph':lines2[4][1],'chips':expr[:2],'model':lines2[6][1],'check':['Incluí uma expressão','Falei com clareza']}}]
 fr=[{'k':'cover','art':art(idx,work),'sub':f'Espanhol para brasileiros · A1 · {topic} · em 10 minutos','badge':'A1','snd':'bell','say':f'Hoje: {topic}. A obra {work} abre a situação.','obra':f'{work} · {year}','coach':f'Objetivo: {topic}, com uma resposta própria.','levelProgression':'Base A1: fórmulas sociais, frases curtas e compreensão guiada.'}]
 if n!=71001: fr.append({'k':'review','prev':'episódio anterior','work':work,'recap':[[w,PT.get(w,w)] for w in vocab[:4]],'bag':[{'ic':'🔤','l':'Palavras','items':[{'ic':'🔤','t':w,'pt':PT.get(w,w)} for w in vocab[:4]]},{'ic':'🏃','l':'Verbos','items':[{'ic':'🏃','t':x,'pt':VERBPT[x]} for x in verbs]},{'ic':'💬','l':'Expressões','items':[{'ic':'💬','t':x,'pt':x} for x in expr]}],'lead':'Abra a mochila e recupere a aula anterior.','next':topic,'say':'Recupere e avance.'})
 fr += [{'k':'hotscene','title':'Explore a cena','hint':'Toque nos elementos e ouça.', 'hot':hot,'say':'Observe a situação antes de responder.'},scene(lines),{'k':'pgsheet','title':'Palavras que aparecem','items':[[w,PT.get(w,w),pron(w)] for w in vocab],'say':'Toque e conecte palavra, som e sentido.'},{'k':'pgrule','title':'Descubra o padrão','focus':f'Para {topic}, combine uma fórmula simples com uma ação.','examples':[[lines[1][1],lines[1][2]],[lines[3][1],lines[3][2]],[lines[5][1],lines[5][2]]],'say':'Observe o padrão antes de repetir.'},{'k':'pgmold','title':'Monte a frase','pages':[{'label':'Quem','items':['Yo','Tú','La persona local']},{'label':'Ação','items':verbs},{'label':'Detalhe','items':vocab[:3]}],'say':'Monte três frases próprias.'},{'k':'pgsheet','title':'Vocabulário ativo','items':[[w,PT.get(w,w),pron(w)] for w in vocab],'say':'Use cada palavra em uma frase.'},{'k':'verbs','title':'Verbos em ação','items':[{'v':x,'ic':'🏃','pt':VERBPT[x],'f':[['uso',f'Yo {x} en esta situación.']], 'ex':[f'Yo {x} en esta situación.',f'Eu {VERBPT[x]} nesta situação.'],'note':pron(x)} for x in verbs],'tip':'Observe quem faz a ação.','say':'Veja os verbos em contexto.'},{'k':'vplay','title':'Pratique os verbos','rounds':[{'say':x,'opts':[x]+verbs[(i+1)%4:(i+3)%4],'a':0,'why':'O verbo completa a ação da situação.'} for i,x in enumerate(verbs)],'say':'Escolha e repita.'},{'k':'pgexp','title':'Expressões em uso','items':[{'ic':'💬','en':x,'tag':'Na situação','pt':x,'use':f'Use esta expressão ao {topic}.','ex':[x,x]} for x in expr],'say':'Leve as expressões para a conversa.'},scene(lines2,'street'),{'k':'pgsheet','title':'Frases reais','items':[[l[1],l[2]] for l in lines2[:6]],'say':'Leia e ouça as frases.'},{'k':'pgsheet','title':'Compreensão','items':[['¿Qué necesitas?', 'O que você precisa?'],[lines2[0][1],lines2[0][2]],[lines2[4][1],lines2[4][2]]],'say':'Relacione intenção e resposta.'},{'k':'pglab','short':'escuta','ex':[[x,x] for x in vocab[:3]],'rounds':[{'t':'w','say':x,'opts':[x]+vocab[(i+1)%6:(i+3)%6],'a':0,'why':'A palavra aparece na cena e no vocabulário.'} for i,x in enumerate(vocab[:3])],'title':'Laboratório de sons','say':'Treine o som antes de falar.'},{'k':'pgsheet','title':'Repare e transforme','items':[[lines[1][1],lines[3][1]],[lines2[0][1],lines2[2][1]],[expr[0],expr[1]]],'say':'Transforme a frase mantendo a intenção.'},{'k':'pgspeak','title':'Sua vez de falar','items':pgspeak,'who':'polly','say':'Repita e personalize.','rs':'street','chars':[['polly',35,0,1.0],['tom',68,1,1.0]]},{'k':'pgmission','title':'Missão: sua vez','missions':missions,'say':'Escolha uma missão e produza.'},{'k':'wrap','title':'Revisão e próxima parada','recap':[[l[0],l[1]] for l in lines[:4]],'teaser':{'t':'Próximo episódio','d':'A próxima situação amplia este repertório.'},'coach':f'Fechamento: retome {topic} e prepare a próxima situação.'}]
 return {'n':n,'t':title,'s':f'{region} · {topic} · referencia: {work} · {year}','sc':'plaza','a':{'k':'obra cultural','w':work,'y':year,'d':f'{work} é a referência cultural desta situação.'},'h':{'l':lines[0][1],'src':work,'tr':lines[0][2]},'p':f'Hoje vamos praticar: {topic}.','g':{'t':topic},'v2':True,'o':n,'baked':True,'lv':'A1','v':v,'rs':'plaza','std':3,'fr':fr,'pl':f'{topic} · {work}','cefr':'A1','dele':'A1','region':region,'authorship':'authorial-a1-pilot','presentation':'regular-pilot-v1','pilot':1}

paths=glob.glob('data/es-a1_*.json')
changed=[]; targets=set(range(7071121,7071201))
for p in paths:
 data=json.load(open(p)); dirty=False
 for i,e in enumerate(data):
  if e.get('n') in targets:
   data[i]=make(e['n'],e['n']-7071121); dirty=True
 if dirty:
  with open(p,'w') as fh: json.dump(data,fh,ensure_ascii=False,separators=(',',':'))
  changed.append(p)
print('changed',changed)
